HAL_UART_Transmit(&huart1, frame, sizeof(frame), 100);

// 发送传感器数据帧
uint8_t sendSensorData(float temp, float humi) {
    uint8_t buf[6];
    buf[0] = 0xAA;  // 帧头
    buf[1] = 0x01;  // 设备ID
    buf[2] = (uint8_t)(temp * 10);  // 温度*10
    buf[3] = (uint8_t)(humi * 10);  // 湿度*10
    buf[4] = buf[0] ^ buf[1] ^ buf[2] ^ buf[3];  // 校验
    buf[5] = 0x0D;  // 帧尾
    return HAL_UART_Transmit(&huart1, buf, 6, 100);
}

// 阻塞接收
