int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_USART1_UART_Init();

    // 启动中断接收
    HAL_UART_Receive_IT(&huart1, &rxByte, 1);

    while (1) {
